@namespace sv_58d1f3bf4001437e9bbf18205d637827.Components.Pages.Settings
@using sv_58d1f3bf4001437e9bbf18205d637827.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Appearance Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                <label class="radio-item">
                    <input type="radio" name="theme" value="Light" checked="@(_theme == "Light")" @onchange="@(() => _theme = "Light")" />
                    <span>Light</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="theme" value="Dark" checked="@(_theme == "Dark")" @onchange="@(() => _theme = "Dark")" />
                    <span>Dark</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="theme" value="System" checked="@(_theme == "System")" @onchange="@(() => _theme = "System")" />
                    <span>System</span>
                </label>
            </div>
        </div>

        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Small" checked="@(_fontSize == "Small")" @onchange="@(() => _fontSize = "Small")" />
                    <span>Small</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Medium" checked="@(_fontSize == "Medium")" @onchange="@(() => _fontSize = "Medium")" />
                    <span>Medium</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Large" checked="@(_fontSize == "Large")" @onchange="@(() => _fontSize = "Large")" />
                    <span>Large</span>
                </label>
            </div>
        </div>

        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="_language">
                <option value="en">English</option>
                <option value="es">Spanish</option>
                <option value="fr">French</option>
                <option value="de">German</option>
                <option value="ja">Japanese</option>
                <option value="zh">Chinese</option>
            </select>
        </div>

        <div class="form-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="_compactMode" />
                <span class="toggle-label">Compact Mode</span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="preview-area @GetPreviewClasses()">
            <h4>Live Preview</h4>
            <p>This is how your content will appear with the selected settings.</p>
            <div class="preview-card">
                <strong>Sample Card</strong>
                <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>
                <button class="btn btn-primary">Sample Button</button>
            </div>
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving..." : "Save")
            </button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Appearance settings saved!</div>
        }
    }
</div>

@code {
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{_theme.ToLowerInvariant()} font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

